import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import {day,slug,redact,settings,indexChats,parseLocal,parseExport,startServer,unzipConversations} from './chat-rat-20261016.mjs';
async function fixture(t){const root=await fs.mkdtemp(path.join(os.tmpdir(),'chat-rat-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const cfg=settings(root,path.join(root,'library'));const file=path.join(cfg.codex,'sessions','source-20261016.jsonl');await fs.mkdir(path.dirname(file),{recursive:true});return {cfg,file};}
const rows=[{type:'session_meta',payload:{id:'test-chat',timestamp:'2026-10-16T02:00:00Z'}},{type:'turn_context',payload:{model:'model-a'}},{type:'response_item',payload:{type:'message',role:'user',content:[{type:'input_text',text:'Hello'}]}},{type:'response_item',payload:{type:'message',role:'assistant',content:[{type:'output_text',text:'Hi there'}]}},{type:'turn_context',payload:{model:'model-b'}},{type:'response_item',payload:{type:'message',role:'assistant',content:[{type:'output_text',text:'Second model'}]}}];
const encode=rs=>rs.map(r=>JSON.stringify(r)).join('\n')+'\n';
test('Denver calendar dates and safe model names',()=>{assert.equal(day('2026-10-16T02:00:00Z'),'20261015');assert.equal(day('bad'),'unknown-date');assert.equal(slug('../../CON'),'model-con');assert.equal(slug('GPT 6/Astra'),'gpt-6-astra');});
test('known secret patterns redacted',()=>assert.equal(redact('sk-abcdefghijklmnopqrstuv'),'[REDACTED]'));
test('same session split across files retains both histories without duplicating repeats',async t=>{const {cfg,file}=await fixture(t);await fs.writeFile(file,encode(rows));const second=path.join(path.dirname(file),'fragment-20261016.jsonl');await fs.writeFile(second,encode([rows[0],rows[1],rows[2],{type:'response_item',payload:{type:'message',role:'assistant',content:[{type:'output_text',text:'A distinct fragment'}]}}]));await indexChats(cfg);let state=JSON.parse(await fs.readFile(path.join(cfg.library,'chat-index-20261016.json')));let transcript=JSON.parse(await fs.readFile(path.join(cfg.library,state.chats[0].files[0].replace(/\.md$/,'.json'))));assert.equal(transcript.messages.length,4);await fs.appendFile(second,'\n');await indexChats(cfg);transcript=JSON.parse(await fs.readFile(path.join(cfg.library,state.chats[0].files[0].replace(/\.md$/,'.json'))));assert.equal(transcript.messages.length,4);});
test('incremental saving, multiple models, missing file recovery and refresh',async t=>{const {cfg,file}=await fixture(t);await fs.writeFile(file,encode(rows));let r=await indexChats(cfg);assert.equal(r.added,1);assert.deepEqual(r.models,['model-a','model-b']);const index=JSON.parse(await fs.readFile(path.join(cfg.library,'chat-index-20261016.json')));const files=index.chats[0].files;assert.equal(files.length,2);assert.match(files[0],/20261015/);const output=path.join(cfg.library,files[0]);const before=(await fs.stat(output)).mtimeMs;r=await indexChats(cfg);assert.equal(r.added,0);assert.equal(r.unchanged,1);assert.equal((await fs.stat(output)).mtimeMs,before);await fs.unlink(output);r=await indexChats(cfg);assert.equal(r.updated,1);assert.match(await fs.readFile(output,'utf8'),/Hello/);await fs.appendFile(file,encode([{type:'response_item',payload:{type:'message',role:'user',content:[{type:'input_text',text:'New message'}]}}]));r=await indexChats(cfg);assert.equal(r.updated,1);assert.match(await fs.readFile(output,'utf8'),/New message/);});
test('injected instructions and internal reasoning excluded; partial records visible',async t=>{const {file}=await fixture(t);await fs.writeFile(file,encode([...rows,{type:'response_item',payload:{type:'message',role:'user',content:[{type:'input_text',text:'<environment_context>injected'}]}},{type:'response_item',payload:{type:'message',role:'assistant',channel:'analysis',content:[{type:'output_text',text:'private reasoning'}]}}])+'{"partial":');const r=await parseLocal(file,'codex');assert.equal(r.malformed,1);assert.equal(r.chats[0].messages.length,3);});
test('Claude tool results omitted; models preserved',async t=>{const {file}=await fixture(t);await fs.writeFile(file,encode([{type:'custom-title',customTitle:'A title'},{type:'user',sessionId:'c1',message:{content:[{type:'text',text:'Hi'}]}},{type:'user',message:{content:[{type:'tool_result',content:'secret tool output'}]}},{type:'assistant',message:{model:'claude-test',content:[{type:'thinking',thinking:'private'},{type:'text',text:'Hello'}]}}]));const r=await parseLocal(file,'claude-code');assert.equal(r.chats[0].title,'A title');assert.equal(r.chats[0].messages.length,2);assert.deepEqual(r.chats[0].models,['claude-test']);});
test('official exports preserve branches and unknown models',()=>{const chats=parseExport([{id:'web',title:'Branches',mapping:{a:{id:'a',parent:null,message:{author:{role:'assistant'},content:{parts:['One']},metadata:{model_slug:'gpt-test'}}},b:{id:'b',parent:null,message:{author:{role:'assistant'},content:{parts:['Two']}}}}}]);assert.equal(chats[0].messages.length,2);assert.deepEqual(chats[0].models,['gpt-test','unknown']);});
test('pet harness import preserves pet and session',()=>{const [c]=parseExport({conversations:[{source:'pet-program',id:'h1',pet:'chat-rat',harnessSession:'seat-session',started:'2026-10-16',messages:[{role:'assistant',model:'local-model',text:'Hello'}]}]});assert.equal(c.pet,'chat-rat');assert.equal(c.harnessSession,'seat-session');assert.deepEqual(c.models,['local-model']);assert.throws(()=>parseExport([{messages:[]}]),/require/);});
test('malformed export reported while good sources save',async t=>{const {cfg,file}=await fixture(t);await fs.writeFile(file,encode(rows));await fs.mkdir(path.join(cfg.library,'inbox'),{recursive:true});await fs.writeFile(path.join(cfg.library,'inbox','broken-20261016.json'),'{');const r=await indexChats(cfg);assert.equal(r.added,1);assert.equal(r.errors.length,1);});
test('ZIP reads only conversations JSON, never extracts paths',()=>{const raw=Buffer.from('[]'),name=Buffer.from('../../conversations.json');const local=Buffer.alloc(30);local.writeUInt32LE(0x04034b50);local.writeUInt32LE(raw.length,18);local.writeUInt32LE(raw.length,22);local.writeUInt16LE(name.length,26);const central=Buffer.alloc(46);central.writeUInt32LE(0x02014b50);central.writeUInt32LE(raw.length,20);central.writeUInt32LE(raw.length,24);central.writeUInt16LE(name.length,28);const end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(1,10);end.writeUInt32LE(local.length+name.length+raw.length,16);assert.deepEqual(unzipConversations(Buffer.concat([local,name,raw,central,name,end])),[]);});
test('server rejects unauthenticated, cross-origin and traversal; OFF blocks save',async t=>{const {cfg}=await fixture(t);const port=43129;const {server,url}=await startServer(cfg,port);t.after(()=>new Promise(resolve=>server.close(resolve)));assert.equal((await fetch(url+'/api/status')).status,403);const html=await (await fetch(url)).text();const token=html.match(/const token='([a-f0-9]+)'/)[1];const headers={'X-Chat-Rat-Token':token};assert.equal((await fetch(url+'/api/status',{headers})).status,200);assert.equal((await fetch(url+'/api/save',{method:'POST',headers:{...headers,Origin:'http://evil.invalid'}})).status,403);assert.equal((await fetch(url+'/api/folder?folder=..',{method:'POST',headers})).status,403);await fetch(url+'/api/power?on=false',{method:'POST',headers});assert.equal((await fetch(url+'/api/save',{method:'POST',headers})).status,409);});
